@import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@300;400;600;700&display=swap');

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000; /* Αλλαγή από #FFFFFF για επαρκή αντίθεση */
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  font-weight: 300;
  letter-spacing: 0.5px;
  padding-top: 94px; /* fixed nav offset */
}

/* ---------- TYPOGRAPHY ---------- */
.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  font-weight: 600;
  line-height: normal;
}

.root h1,
.root h2 {
  font-weight: 700;
}

.root h1 { font-size: 48px; }
.root h2 { font-size: 36px; }
.root h3 { font-size: 32px; }
.root h4 { font-size: 28px; }
.root h5 { font-size: 24px; }
.root h6 { font-size: 22px; }

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

/* ---------- NAV ---------- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 2px 5px rgba(0,0,0,0.1);
  padding: 20px 0;
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 15px;
}

.logo {
  text-decoration: none;
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  text-align: center;
  margin: 0 30px;
  padding: 0;
  display: inline-block;
}

.brand {
  /* Brand component styles inherited */
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* ---------- HERO ---------- */
.hero {
  padding-top: 0;
}

.heroContainer {
  position: relative;
  overflow: hidden;
  height: 580px;
  background: var(--vt-surface-2);
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-sizing: border-box;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.1);
}

.heroText h1 {
  margin-top: auto;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.heroText h1 span {
  color: var(--vt-accent);
}

.heroText p {
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  transition: all 0.3s;
  margin-right: 1.5rem;
}

.customLink:hover {
  background: var(--vt-line);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
}

/* ---------- ABOUT ---------- */
.about {
  padding: 7rem 0;
  background: var(--vt-surface);
}

.aboutInner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  padding: 0 15px;
}

.about h2 {
  margin-bottom: 2rem;
}

.about p {
  text-align: left;
}

/* ---------- GALLERY ---------- */
.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  width: 100%;
}

.galleryItem {
  flex: 1;
  padding: 0;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* ---------- TIMELINE ---------- */
.timelineSection {
  padding: 7rem 0;
  background: var(--vt-surface-2);
}

.timelineTitle {
  text-align: center;
  margin-bottom: 4rem;
}

.timeline {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  padding: 0 15px;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
}

.timelineNode {
  display: flex;
  position: relative;
  margin-bottom: 2rem;
}

.timelineNode.odd {
  flex-direction: row-reverse;
}

.timelineNode.even {
  flex-direction: row;
}

.timelineIcon {
  flex: 0 0 80px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  position: relative;
  z-index: 100;
}

.timelineIcon::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: 1;
}

.iconDot {
  width: 80px;
  height: 80px;
  display: block;
  position: relative;
  z-index: 2;
}

.iconDot::after {
  content: "";
  width: 20px;
  height: 20px;
  background: var(--vt-accent);
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.timelineContent {
  flex: 1;
  background: var(--vt-surface);
  border-radius: 0 0 0.25rem 0.25rem;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.1);
  padding: 0;
  position: relative;
  border-top: 3px solid var(--vt-surface-deep);
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

/* Odd: content on right, icon on left; arrow points right */
.timelineNode.odd .timelineContent {
  margin-left: 1rem;
}
.timelineNode.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Even: content on left, icon on right; arrow points left */
.timelineNode.even .timelineContent {
  margin-right: 1rem;
}
.timelineNode.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

@media (max-width: 767px) {
  .timeline::before {
    left: 33px;
    height: 90%;
  }
  .timelineNode.odd,
  .timelineNode.even {
    flex-direction: row;
    margin-left: 50px;
  }
  .timelineIcon {
    position: absolute;
    left: -50px;
    top: 0;
  }
  .timelineContent {
    margin-left: 0 !important;
    margin-right: 0 !important;
  }
  .timelineNode.odd .timelineContent h3::after,
  .timelineNode.even .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
  }
}

/* ---------- FOOTER ---------- */
.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0 2rem;
}

.footerRow {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  padding: 0 15px;
}

.footerCol {
  flex: 1 1 250px;
  margin: 1rem 0;
}

.footerCol h5 {
  margin-bottom: 1.5rem;
  font-weight: 600;
}

.footerCol p,
.footerCol a {
  font-size: 16px;
  color: var(--vt-ink-soft);
}

.copyright {
  text-align: center;
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--vt-line);
}

.copyright p {
  font-size: 16px;
}

/* ---------- RESPONSIVE ---------- */
@media screen and (min-width: 1600px) {
  .heroContainer {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }
  .root h1 { font-size: 38px; }
  .root h2 { font-size: 32px; }
  .root h3 { font-size: 26px; }
  .root h4 { font-size: 24px; }
  .root h5 { font-size: 20px; }
  .root h6 { font-size: 18px; }

  .nav {
    padding: 10px 0;
  }
  .navIn {
    flex-direction: column;
    gap: 10px;
  }
  .navLinks {
    gap: 1rem;
    flex-wrap: wrap;
    justify-content: center;
  }

  .heroContainer {
    height: auto;
  }
  .heroText {
    position: relative;
    bottom: auto;
    left: 0;
    width: auto;
    margin: -100px 15px 0;
    padding: 2rem;
  }
  .heroImage {
    height: 400px;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
    margin: -80px 15px 0;
  }
  .heroText h1 span {
    min-width: 125px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }
  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }
  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .root h1 { font-size: 32px; }
  .timeline::before {
    left: 42px;
  }
}
